/**
 * "When should I remind you?" in the introduction (sales plan G, 23 Oct
 * 2026: only 15% came back on day 1 or 2, and the reminder was on for 24% on
 * Android, 7% on the web, none on the desktop). The permission is asked at
 * the tap, before there is an account; the time waits in the draft and is
 * saved, with the goal, by the first card once the account exists
 * (`applyIntroChoices`). Nothing here blocks the sign-up: a refusal, a
 * failure or "Not now" each go on to the next question.
 */
import { patchSettings, setReminder } from '@/db/mutations.js';
import { setMeta } from '@/db/schema.js';
import { isWebTab } from '@/features/reminder/webOffer.js';
import { remindsHere } from '@/features/session/reminderOffer.js';
import { DEFAULT_REMINDER_TIME, startReminder } from '@/features/settings/reminders.js';
import { localTimeZone } from '@/lib/format.js';
import { isDesktopShell, isNativeShell } from '@/lib/platform/detect.js';
import { platform } from '@/lib/platform/index.js';
import { syncSoon } from '@/sync/store.js';
import type { IntroDraft, ReminderAnswer } from './introDraft.js';

/**
 * How this device can remind, which decides the words and what the tap asks:
 * - `phone`: the Android and iPhone apps, a local note every day (the OS asks).
 * - `computer`: the desktop app, whose core hands the plan to the system and
 *   asks itself when it first gets one.
 * - `browser`: a tab that can take Web Push (the server has a key and the
 *   browser the Push API): a note in this browser after a day away.
 * - `email`: any other tab: an e-mail after a day away, to the address the
 *   account is about to have.
 */
export type ReminderVariant = 'phone' | 'computer' | 'browser' | 'email';

/**
 * How long a browser tab waits for the server's config (the VAPID key)
 * before choosing its words: the e-mail ones, which need no key, are then
 * the honest choice. The same bound as the web offer's `CONFIG_WAIT_MS`.
 */
export const VARIANT_WAIT_MS = 1500;

export function reminderVariant(webPushReady: boolean): ReminderVariant {
  if (isNativeShell() && platform.reminders.allow !== undefined) return 'phone';
  if (isDesktopShell()) return 'computer';
  if (isWebTab() && webPushReady) return 'browser';
  return 'email';
}

/**
 * The hours in which the moment somebody is setting up is taken as their
 * time to practise. Outside them (late at night, very early) the evening
 * default is the kinder guess. Rules of the question, not data.
 */
export const OWN_HOUR_FROM = 7;
export const OWN_HOUR_TO = 22;

/**
 * The server's e-mail reminder is sent between 09:00 and 20:00 (the day-2
 * note's window, as `EMAIL_EARLIEST_HOUR`/`EMAIL_LATEST_HOUR` in the web
 * offer), so an e-mail reminder never names a time outside it.
 */
export const EMAIL_FROM = '09:00';
export const EMAIL_TO = '20:00';

/**
 * The time the question starts on: the hour the learner is setting up in,
 * which is when they had a moment for this, else 20:00
 * (`DEFAULT_REMINDER_TIME`, Settings' own default). For an e-mail it is kept
 * inside the hours the server writes in.
 */
export function introReminderTime(variant: ReminderVariant, now: Date = new Date()): string {
  const hour = now.getHours();
  const own = hour >= OWN_HOUR_FROM && hour <= OWN_HOUR_TO;
  const time = own ? `${String(hour).padStart(2, '0')}:00` : DEFAULT_REMINDER_TIME;
  return variant === 'email' ? withinEmailHours(time) : time;
}

/** A time moved into the e-mail hours ("HH:mm" compares as text). */
export function withinEmailHours(time: string): string {
  if (time < EMAIL_FROM) return EMAIL_FROM;
  if (time > EMAIL_TO) return EMAIL_TO;
  return time;
}

/** What the tap came to: an answer for the draft, or a failure to say and retry. */
export type PermissionResult = ReminderAnswer | 'failed';

/**
 * Asks for what this device needs to remind, from the tap itself (browsers
 * only ask from a gesture). The phone apps ask the OS (Android 13+ and iOS
 * show their dialog); a browser subscribes with the server's key, which the
 * first registration after sign-up hands to the server (`registerDevice`
 * sends the subscription it finds). The desktop app and e-mail need nothing
 * now.
 */
export async function askToRemind(variant: ReminderVariant, webPushKey?: string): Promise<PermissionResult> {
  try {
    if (variant === 'phone') {
      if (platform.reminders.allow === undefined) return 'on';
      return (await platform.reminders.allow()) === 'granted' ? 'on' : 'denied';
    }
    if (variant === 'browser') {
      if (webPushKey === undefined) return 'failed';
      const outcome = await platform.webPush.subscribe(webPushKey);
      if (outcome.status === 'subscribed') return 'on';
      return outcome.status === 'denied' ? 'denied' : 'failed';
    }
    return 'on';
  } catch {
    return 'failed';
  }
}

/**
 * Saves what the introduction chose, once the account exists (the first
 * card's set-up): the goal on this device, and the reminder through the same
 * writes as Settings, so the server and every other device hear it with the
 * next sync. "Not now" saves nothing and leaves the later asks in place; an
 * answer in the phone or desktop apps (on or refused) marks the reminder asked, so the
 * ask after the first word does not come again. Never throws: none of this
 * may stand between the learner and their first card.
 */
export async function applyIntroChoices(draft: IntroDraft, now: Date = new Date()): Promise<void> {
  try {
    if (draft.goal !== undefined) {
      await setMeta('learningGoal', { ...draft.goal, at: now.toISOString() });
    }
    const reminder = draft.reminder;
    if (reminder === undefined || reminder.answer === 'later') return;
    if (remindsHere()) await setMeta('reminderAsked', true);
    if (reminder.answer === 'denied') return;
    await setReminder(reminder.time, localTimeZone());
    // A browser reminder, like the web offer's, also turns e-mail reminders
    // on: the learner just asked to be reminded.
    if (isWebTab()) await patchSettings({ emailNudges: true });
    void syncSoon();
    // The phone and desktop apps plan their notes now (the permission was
    // given at the tap; the desktop core asks if it must).
    if (!isWebTab()) void startReminder().catch(() => undefined);
  } catch {
    // Settings still holds the switch.
  }
}
