/**
 * The plan screen's numbers (onboarding v2 spec §4.5, §6): how many new
 * words a day fit the minutes, from `planPreview` in core with the server's
 * measured seconds a card and recall (or their named defaults), never from
 * anything else.
 */
import { INTERVALS, PLAN_HORIZON_DAYS, planPreview, type PlanPreview } from '@lexpad/core';
import { t } from '@/i18n/index.js';
import { planRecall, secondsPerCard } from '@/lib/cardTime.js';
import type { Minutes, Why } from './introDraft.js';

/**
 * The minutes a plan starts on for each reason (spec §6): an exam and a move
 * abroad have a date coming, so they start higher. A starting point only;
 * the learner changes it on the same screen. Mirror it in config if the
 * marketer wants to tune it.
 */
export const DEFAULT_MINUTES: Readonly<Record<Why, Minutes>> = {
  exam: 15,
  work: 10,
  move: 15,
  read: 10,
  travel: 10,
  me: 10,
};

/**
 * The minutes the plan shows: the learner's choice, else the reasons'
 * default. With several reasons the plan starts on the highest of their
 * defaults: somebody learning for work and for an exam still has the exam's
 * date coming. No reason at all starts where "just for me" does.
 */
export function planMinutes(minutes: Minutes | undefined, why: readonly Why[]): Minutes {
  if (minutes !== undefined) return minutes;
  const defaults = (why.length > 0 ? why : (['me'] as const)).map((reason) => DEFAULT_MINUTES[reason]);
  return Math.max(...defaults) as Minutes;
}

/**
 * The reason the plan is labelled with: the first one picked, which is the
 * one the learner thought of first. The others are counted beside it.
 */
export function planReason(why: readonly Why[]): { lead: Why; more: number } {
  return { lead: why[0] ?? 'me', more: Math.max(0, why.length - 1) };
}

/** The plan for these minutes, on the measured numbers. */
export function planFor(minutes: Minutes): PlanPreview {
  return planPreview({ minutesPerDay: minutes, secondsPerCard: secondsPerCard(), recall: planRecall() });
}

/** "19 January": the horizon's last day, in the learner's own locale. */
export function planDate(now: Date, locale?: string): string {
  const end = new Date(now.getFullYear(), now.getMonth(), now.getDate() + PLAN_HORIZON_DAYS);
  return new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'long' }).format(end);
}

/** "1, 3, 7 and 21": the days a right answer waits, from the engine's own INTERVALS. */
export function intervalDays(): string {
  const days = INTERVALS.filter((day) => day > 0);
  const last = days[days.length - 1] ?? 0;
  return t('onb.plan.daysList', { list: days.slice(0, -1).join(', '), last });
}
